package bowling

import "errors"

var (
	errNegativeRoll   = errors.New("Negative roll is invalid")
	errTooManyPins    = errors.New("Pin count exceeds pins on the lane")
	errRollAfterEnd   = errors.New("Cannot roll after game is over")
	errIncompleteGame = errors.New("Score cannot be taken until the end of the game")
)

// Game keeps track of the rolls of a bowling game.
type Game struct {
	rolls []int
}

// NewGame returns a new, empty Game.
func NewGame() *Game {
	return &Game{}
}

// nextRoll reports whether the game is over and, if it is not, the maximum
// number of pins the next roll may knock down.
func (g *Game) nextRoll() (over bool, maxPins int) {
	rolls := g.rolls
	i := 0
	for frame := 0; frame < 10; frame++ {
		if frame < 9 {
			if i >= len(rolls) {
				return false, 10
			}
			if rolls[i] == 10 { // strike completes the frame
				i++
				continue
			}
			if i+1 >= len(rolls) {
				return false, 10 - rolls[i]
			}
			i += 2
		} else {
			// Tenth frame: a strike or spare in the first two rolls
			// earns one or two fill balls.
			n := len(rolls) - i
			switch {
			case n == 0:
				return false, 10
			case n == 1:
				if rolls[i] == 10 {
					return false, 10
				}
				return false, 10 - rolls[i]
			case n == 2:
				if rolls[i] == 10 {
					if rolls[i+1] == 10 {
						return false, 10
					}
					return false, 10 - rolls[i+1]
				}
				if rolls[i]+rolls[i+1] == 10 {
					return false, 10
				}
				return true, 0 // open frame ends the game
			default:
				return true, 0
			}
		}
	}
	return true, 0
}

// Roll records a roll that knocked down the given number of pins.
func (g *Game) Roll(pins int) error {
	over, maxPins := g.nextRoll()
	if over {
		return errRollAfterEnd
	}
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > maxPins {
		return errTooManyPins
	}
	g.rolls = append(g.rolls, pins)
	return nil
}

// Score returns the total score of the game.
// It returns an error if the game is not complete.
func (g *Game) Score() (int, error) {
	over, _ := g.nextRoll()
	if !over {
		return 0, errIncompleteGame
	}
	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case g.rolls[i] == 10: // strike
			total += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		case g.rolls[i]+g.rolls[i+1] == 10: // spare
			total += 10 + g.rolls[i+2]
			i += 2
		default: // open frame
			total += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	return total, nil
}

